css:
* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.plegador-widget {
  --title-color: #0E5B67;
  --subtitle-color: #728DA5;
  --text-color: #246975;
  --border-color: #4B83A7;
  --separator-color: #C8DAE5;
  --mechanical-color: #4E4E4E;
  --mechanical-fill: #D7D8DB;

  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  color: var(--text-color);
  font-family: Arial, Helvetica, sans-serif;
  user-select: none;
  pointer-events: none;
  opacity: var(--w-opacity, 1);
}

.plegador-stage {
  position: absolute;
  top: 0;
  left: 0;
  width: 1610px;
  height: 755px;
  transform-origin: top left;
  background: transparent;
}

.screen-header {
  position: absolute;
  top: 14px;
  left: 30px;
  right: 30px;
  height: 56px;
  display: flex;
  align-items: flex-start;
  min-width: 0;
}

.screen-heading {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 5px;
  min-width: 0;
}

.screen-title {
  color: var(--title-color);
  font-size: 28px;
  font-weight: 700;
  line-height: 1.05;
  white-space: nowrap;
}

.screen-subtitle {
  color: var(--subtitle-color);
  font-size: 14px;
  line-height: 1.3;
  white-space: nowrap;
}

.screen-subtitle[hidden] {
  display: none;
}

.process-diagram {
  position: absolute;
  top: 88px;
  left: 30px;
  width: 1550px;
  height: 570px;
  overflow: hidden;
  font-family: Arial, Helvetica, sans-serif;
}

.guide-line {
  fill: none;
  stroke: #82919B;
  stroke-width: 1.3;
}

.axis-line {
  fill: none;
  stroke: #71808A;
  stroke-width: 1.2;
  stroke-dasharray: 14 7 3 7;
}

.center-line {
  fill: none;
  stroke: #82919B;
  stroke-width: 1.3;
}

.mechanical-line {
  fill: none;
  stroke: var(--mechanical-color);
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.machine-body,
.support-body {
  fill: var(--mechanical-fill);
  stroke: var(--mechanical-color);
  stroke-width: 1.5;
}

.machine-inset {
  fill: #EEF1F3;
  stroke: var(--mechanical-color);
  stroke-width: 1.3;
}

.shaft-body,
.shaft-end {
  fill: #E3E7EA;
  stroke: var(--mechanical-color);
  stroke-width: 1.5;
}

.sensor-body {
  fill: #FFFFFF;
  stroke: var(--mechanical-color);
  stroke-width: 1.2;
}

.sensor-mark {
  fill: var(--mechanical-color);
}

.sensor-tag,
.motor-tag {
  fill: #405B6B;
  font-size: 13px;
  font-weight: 700;
  dominant-baseline: middle;
}

.motor-tag {
  text-anchor: end;
}

.motor-circle {
  fill: #FFFFFF;
  stroke: var(--mechanical-color);
  stroke-width: 1.4;
}

.motor-letter {
  fill: var(--mechanical-color);
  font-size: 14px;
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: middle;
}

.screen-footer {
  position: absolute;
  top: 685px;
  left: 30px;
  right: 30px;
  height: 56px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  border-top: 1px solid var(--separator-color);
}

.navigation-left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.visual-button {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 142px;
  height: 40px;
  padding: 0 18px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  background: linear-gradient(180deg, #FFFFFF, #EEF5F8);
  color: #1C5A6B;
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

.brand-label {
  display: flex;
  align-items: center;
  height: 40px;
  color: #009999;
  font-size: 23px;
  font-weight: 700;
  letter-spacing: 1px;
}

js:
"use strict";

(function () {
  const BASE_WIDTH = 1610;
  const BASE_HEIGHT = 755;

  const DEFAULT_TITLE = "LÍNEA 3 / PLEGADOR 01";
  const DEFAULT_SUBTITLE =
    "Vista superior del eje, soportes y sensores";

  let root = null;
  let stage = null;
  let latestWidget = null;
  let currentName = null;
  let initialized = false;

  function fitHeader() {
    if (!stage) return;

    [
      [".screen-title", 28],
      [".screen-subtitle", 14]
    ].forEach(function (entry) {
      const element = stage.querySelector(entry[0]);

      if (!element || element.hidden) return;

      element.style.fontSize = entry[1] + "px";

      if (
        element.clientWidth > 0 &&
        element.scrollWidth > element.clientWidth
      ) {
        element.style.fontSize =
          (entry[1] * element.clientWidth / element.scrollWidth) +
          "px";
      }
    });
  }

  function updateHeader(widget) {
    if (!stage) return;

    const name =
      widget && typeof widget.name === "string"
        ? widget.name.trim()
        : "";

    if (name === currentName) return;
    currentName = name;

    const separator = name.indexOf("//");

    const titleText =
      separator < 0
        ? name
        : name.slice(0, separator).trim();

    const subtitleText =
      separator < 0
        ? DEFAULT_SUBTITLE
        : name.slice(separator + 2).trim();

    const title = stage.querySelector(".screen-title");
    const subtitle = stage.querySelector(".screen-subtitle");

    title.textContent = titleText || DEFAULT_TITLE;
    subtitle.textContent = subtitleText;
    subtitle.hidden = subtitleText === "";

    fitHeader();
  }

  function fitStage() {
    if (!root || !stage) return;

    const width = root.clientWidth;
    const height = root.clientHeight;

    if (width <= 0 || height <= 0) return;

    const scale = Math.min(
      width / BASE_WIDTH,
      height / BASE_HEIGHT
    );

    stage.style.left =
      (width - BASE_WIDTH * scale) / 2 + "px";

    stage.style.top =
      (height - BASE_HEIGHT * scale) / 2 + "px";

    stage.style.transform = "scale(" + scale + ")";
  }

  // Widget visual, sin tags del PLC.
  // NOMBRE en PSI CORE: Título//Subtítulo.
  window.onWidgetUpdate = function (widget) {
    latestWidget = widget;

    if (initialized) {
      updateHeader(widget);
    }
  };

  function initialize() {
    if (initialized) return;

    root = document.querySelector(".plegador-widget");
    stage = document.querySelector(".plegador-stage");

    if (!root || !stage) return;

    initialized = true;
    updateHeader(latestWidget || window.WIDGET || null);
    fitStage();

    if (typeof ResizeObserver !== "undefined") {
      const observer = new ResizeObserver(fitStage);
      observer.observe(root);
    } else {
      window.addEventListener("resize", fitStage);
    }

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(function () {
        fitHeader();
        fitStage();
      });
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initialize, {
      once: true
    });
  } else {
    initialize();
  }
})();
